  expect(() => parseArgs(['node', 'ssg', 'serve', '--port', 'notaport'])).toThrow(
    'Invalid port'
  );
  expect(() => parseArgs(['node', 'ssg', 'serve', '--port', '99999'])).toThrow(
    'Invalid port'
  );
});

