export PATH="/home/drseuss/node/bin:$PATH"; node -e "
const path = require('path');
const { startDevServer } = require('./dist/serve');
(async () => {
  const fs = require('fs/promises');
  const os = require('os');
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-smoke-'));
  const contentDir = path.join(root, 'content');
  await fs.mkdir(contentDir, { recursive: true });
  await fs.writeFile(path.join(contentDir, 'smoke.md'), '---\ntitle: Smoke\n---\n# Smoke\nHello live reload.');
  const server = await startDevServer({ contentDir, outputDir: path.join(root, 'dist'), templateDir: path.join(root, 'templates'), port: 0, host: '127.0.0.1' });
  const res = await fetch('http://127.0.0.1:' + server.port + '/smoke.html');
  const text = await res.text();
  console.log('status', res.status);
  console.log('has title:', text.includes('Smoke'));
  console.log('has ws script:', text.includes('/__ssg_ws'));
  await server.close();
  console.log('closed cleanly');
})().catch(e => { console.error('ERR', e); process.exit(1); });
"

